Tool response:
Tool: find_available_apartments
Description: Find Available Apartments
Parameters:
    {
      "type": "object",
      "properties": {
        "check_in_date": {
          "type": "string",
          "description": "Check-in date in YYYY-MM-DD format",
          "title": "Check In Date"
        },
        "check_out_date": {
          "type": "string",
          "description": "Check-out date in YYYY-MM-DD format",
          "title": "Check Out Date"
        },
        "max_guests": {
          "type": "integer",
          "description": "Maximum number of guests",
          "title": "Max Guests"
        },
        "max_price_per_night": {
          "type": "number",
          "description": "Maximum price per night",
          "title": "Max Price Per Night"
        }
      },
      "required": [
        "check_in_date",
        "check_out_date",
        "max_guests",
        "max_price_per_night"
      ]
    }

